/* Pages 2 to 8 (spec sections 6 to 12). Each page = { eyebrow, title, lede, view(), mount(root) -> cleanup }.
   Every block reads the live server through data.js; `data-api` attributes name the endpoint. */
window.ARAN = window.ARAN || {};
(function (A) {
  const U = A.ui, H = A.helpers, $ = U.$, $$ = U.$$;
  const P = (A.pages = {});

  /* ------------------------------------------------------------- shared radar */
  const R0 = 140, CX = 190, CY = 190;
  A.radarSVG = (windows) => {
    const ang = (k) => (k / 7) * Math.PI * 2 - Math.PI / 2, pt = (k, z) => [CX + Math.cos(ang(k)) * R0 * z, CY + Math.sin(ang(k)) * R0 * z];
    const poly = (w) => w.z.map((z, k) => pt(k, Math.min(1, z)).map((v) => v.toFixed(1)).join(',')).join(' ');
    const rings = [0.25, 0.5, 0.75, 1].map((r) => `<polygon class="gr" points="${A.FEATURES.map((_, k) => pt(k, r).map((v) => v.toFixed(1)).join(',')).join(' ')}"/>`).join('');
    const axes = A.FEATURES.map((n, k) => { const [x, y] = pt(k, 1), [lx, ly] = pt(k, 1.16); return `<line class="gr" x1="${CX}" y1="${CY}" x2="${x}" y2="${y}"/><text class="ax" x="${lx}" y="${ly}" text-anchor="middle">${n}</text>`; }).join('');
    const band = `<polygon class="band" points="${A.FEATURES.map((_, k) => pt(k, 0.7).map((v) => v.toFixed(1)).join(',')).join(' ')}"/><polygon class="inner" points="${A.FEATURES.map((_, k) => pt(k, 0.1).map((v) => v.toFixed(1)).join(',')).join(' ')}"/>`;
    const last = windows.slice(-8);
    return `<svg class="radar" viewBox="0 0 380 380" role="img" aria-label="Radar of the last ${last.length} traffic windows against the learned normal band">${rings}${band}${axes}${last.map((w, i) => `<polygon class="win ${w.alert ? 'alert' : ''} ${i === last.length - 1 ? 'newest' : ''}" points="${poly(w)}"/>`).join('')}</svg>`;
  };
  const ring = (frac, text) => `<svg class="ring" viewBox="0 0 116 116" role="img" aria-label="learning progress"><circle class="bg" cx="58" cy="58" r="50"/><circle class="fg" cx="58" cy="58" r="50" stroke-dasharray="${(314 * frac).toFixed(1)} 314"/><text x="58" y="64">${text}</text></svg>`;
  const alertBox = (a, o) => `<div class="alert ${o && o.fresh ? 'new' : ''} ${a.label === 'attack' ? 'confirmed' : a.label === 'normal' ? 'normal' : ''}" data-id="${a.id}" data-api="GET /api/immune → alerts[]"><div class="between"><b>${o && o.warn ? '⚠ ' : ''}${a.src} → ${a.sink}</b><span class="small muted">${U.ago(a.at)} · score <span class="mono">${a.score}</span></span></div><ul>${a.reasons.map((r) => `<li>${r}</li>`).join('')}</ul><div class="mono caption muted">n=${a.n} raw=${a.raw_frac} detok=${a.detok_rate} classes=${(a.classes || []).join(',')}</div>${a.label ? `<div style="margin-top:10px">${a.label === 'attack' ? U.pill('confirmed attack (memory cells added)', 'danger') : U.pill('marked normal (detectors removed)', 'ok')}</div>` : o && o.compact ? '' : `<div class="row" style="margin:12px 0 0"><button class="btn danger sm" data-lab="attack" data-id="${a.id}">Confirm attack</button><button class="btn ghost sm" data-lab="normal" data-id="${a.id}">Mark as normal</button></div>`}</div>`;

  /* shared immune scene (tour chapter 10): follows GET /api/tour/immune-radar (idle / learning / watching) */
  const legend = `<div class="legend" style="flex-direction:column;align-items:flex-start;gap:8px;margin:0"><span><i class="sw" style="background:var(--band-color);border:1px solid var(--success-color)"></i>Normal range it learned</span><span><i class="sw" style="border:1.5px solid var(--info-color)"></i>A 30-second traffic window</span><span><i class="sw" style="background:var(--leak-bg-color);border:1.5px solid var(--leak-color)"></i>Outside normal: alert</span></div>`;
  const clock = (s) => `${Math.floor(s / 60)}:${String(Math.round(s) % 60).padStart(2, '0')}`;
  A.labelAlert = async (id, lab) => { try { await A.label(id, lab); await A.refresh('immune', 'stats'); } catch (e) { U.toast(e.message); } };
  A.mountImmune = (root, sceneId, alertsId) => {
    const sc = $('#' + sceneId, root), al = $('#' + alertsId, root); let r = null, total = 0, shape = '', msg = '', timer = null, alive = true, seenAlerts = new Set(A.alerts.map((a) => a.id));
    const draw = () => {
      if (!r) return; const mode = r.mode, st = r.state || {};
      if (mode === 'learning') total = Math.max(total, r.learn_left || 0);
      const key = mode + (mode === 'watching' ? '' : st.error || '');
      if (key !== shape) {
        shape = key;
        if (mode === 'idle') sc.innerHTML = `<div class="learn"><div class="pulse">?</div><div><h2 class="h3">Not trained yet.</h2><p class="muted" style="max-width:520px">It must first watch normal traffic: real production log lines replayed through the firewall.</p>${st.error ? U.note('err', U.esc(st.error)) : ''}<div class="row"><label class="field">Seconds<input type="number" id="im-secs" min="30" max="1800" value="360"></label><button class="btn" id="im-learn"><span>Learn normal traffic</span><span class="arr">→</span></button></div></div></div>`;
        else if (mode === 'learning') sc.innerHTML = `<div class="learn"><div id="im-ring"></div><div><h2 class="h3">Learning what “normal” looks like…</h2><p class="muted" style="max-width:520px">Real log lines are flowing through the firewall right now. You can explore other chapters and come back.</p></div></div>`;
        else sc.innerHTML = `<div class="radarwrap"><div id="im-radar"></div><div class="stack">${legend}<div class="small muted">Next check in <b class="mono" id="im-next"></b> · <span id="im-det"></span> detectors</div><div class="stack">${Object.entries(A.DRILLS).map(([k, l]) => `<button class="btn secondary sm" style="width:100%;justify-content:flex-start" data-drill="${k}">⚡ ${l}</button>`).join('')}</div><div id="im-msg">${msg}</div></div></div>`;
        const learn = $('#im-learn', sc); if (learn) learn.onclick = async () => { learn.disabled = true; try { await A.learn(+$('#im-secs', sc).value || 360); total = 0; await tick(); } catch (e) { U.toast(e.message); learn.disabled = false; } };
        $$('[data-drill]', sc).forEach((b) => (b.onclick = async () => { b.disabled = true; try { const d = await A.drill(b.dataset.drill); msg = U.note('ok', `${U.esc(d.done)} Watch the radar at the next check (up to ${d.window_seconds}s).`); A.sound.error(); } catch (e) { msg = U.note('err', U.esc(e.message)); } $('#im-msg', sc).innerHTML = msg; b.disabled = false; }));
      }
      if (mode === 'learning') { const left = r.learn_left || 0; $('#im-ring', sc).innerHTML = ring(total ? 1 - left / total : 0, clock(left)); }
      if (mode === 'watching') { $('#im-radar', sc).innerHTML = A.radarSVG(r.windows.slice().reverse()); $('#im-next', sc).textContent = Math.round(r.next_window_in) + 's'; $('#im-det', sc).textContent = st.detectors; }
      al.innerHTML = mode === 'watching' ? A.alerts.slice(0, 3).map((a) => alertBox(a, { warn: true, compact: true, fresh: !seenAlerts.has(a.id) })).join('') : '';
      A.alerts.forEach((a) => { if (!seenAlerts.has(a.id)) { seenAlerts.add(a.id); A.sound.error(); } });
    };
    const tick = async () => { try { const [x] = await Promise.all([A.radar(), A.refresh('immune')]); if (!alive) return; r = x; A.lastWindows = x.windows.slice().reverse(); draw(); } catch (e) { sc.innerHTML = U.note('err', U.esc(e.message)); shape = ''; } };
    tick(); timer = setInterval(tick, 2000);
    return () => { alive = false; clearInterval(timer); };
  };

  /* ============================================================ 2 Overview */
  P.overview = {
    eyebrow: 'DATA-FLOW FIREWALL FOR INDIAN BANKS', title: 'Real numbers pass the checksum. Aran’s tokens never do.', lede: 'This console runs Aran’s actual code. Send a request, watch it get protected, trace a leak, erase a customer, and see every number update from the live server.',
    view() {
      const s = A.stats, ev = A.events, sample = ev.flatMap((e) => e.findings.filter((f) => f.type === 'AADHAAR' && f.token && /^\d{12}$/.test(f.token)).map((f) => ({ real: e.before.slice(f.start, f.end).replace(/\D/g, ''), token: f.token }))).filter((x) => x.real.length === 12)[0];
      const mx = Math.max(1, ...Object.values(s.by_type)), ms = (v) => (v == null ? '–' : v + ' ms');
      return `<section class="card plus hero-pair" data-api="GET /api/events?limit=6 → newest event with a 12-digit Aadhaar token"><span class="label">Latest Aadhaar this server protected</span>${sample ? `${U.idStrip(sample.real, 'real', 'passes Verhoeff · real (generated customer)', true)}<div class="mono caption muted" style="margin:16px 0">↓ tokenised before it left the API</div>${U.idStrip(sample.token, 'token', 'fails Verhoeff · protected Aran token', true)}` : `<h2 class="h3" style="margin-top:12px">${s.requests ? 'No Aadhaar number has gone through yet' : 'Nothing has gone through this server yet'}</h2><p class="muted" style="max-width:640px">Send a few generated bank requests and every number on this page fills in from the live firewall. Nothing here is a real person.</p><div class="row" style="display:flex;flex-wrap:wrap;gap:10px;margin-top:16px"><button class="btn" data-ov="send"><span>Send 6 bank requests</span><span class="arr">→</span></button><button class="btn secondary" data-ov="replay" ${s.replay.running ? 'disabled' : ''}><span>${s.replay.running ? 'Normal traffic is on' : 'Start normal traffic'}</span></button><a class="btn ghost" href="#tour">Take the guided tour</a></div>`}</section>
      <div class="grid g4" style="margin-top:16px">${U.stat('Requests protected', '', `${U.fmt(s.customers)} enrolled customers`, { count: s.requests, bind: 'GET /api/stats → requests' })}${U.stat('Values tokenised', '', `${U.fmt(s.values_passed_raw)} passed raw`, { count: s.values_protected, bind: 'GET /api/stats → values_protected' })}${U.stat('Added latency p95', ms(s.p95_ms), `median ${ms(s.p50_ms)}`, { bind: 'GET /api/stats → p95_ms, p50_ms' })}${U.stat('Immune alerts', '', `${s.open_alerts} open · mode: ${s.immune.mode}`, { count: s.alerts, tone: s.open_alerts ? 'danger' : '', bind: 'GET /api/stats → alerts, open_alerts' })}</div>
      <div class="grid g4" style="margin-top:16px">${U.stat('Tokens issued', '', `${U.fmt(s.vault_tokens)} purpose-bound`, { count: s.tokens_issued })}${U.stat('Keys destroyed', '', `Merkle log: ${s.merkle_size} entries`, { count: s.keys_destroyed })}${U.stat('Normal traffic replay', s.replay.running ? 'On' : 'Off', `${U.fmt(s.replay.lines_sent)} real log lines sent`)}${U.stat('Server uptime', `${Math.floor((s.uptime_s || 0) / 60)} min`, `models loaded in ${s.model_load_seconds}s`)}</div>
      <section class="card plus" style="margin-top:16px" data-api="GET /api/stats → per_minute"><div class="between"><h2 class="h3">Values in the last 30 minutes</h2><span class="small muted">${U.fmt((s.per_minute || []).reduce((a, d) => a + d.requests, 0))} requests</span></div>${(s.per_minute || []).some((d) => d.requests) ? '' : '<p class="muted small" style="margin-top:4px">Bars appear as requests come in, one per minute.</p>'}${s.per_minute ? U.minuteChart(s.per_minute) : ''}</section>
      <div class="grid g2" style="margin-top:16px"><section class="card plus" data-api="GET /api/stats → by_type"><h2 class="h3">Values found by type</h2>${Object.keys(s.by_type).length ? '' : '<p class="muted">Appears after the first request.</p>'}${Object.entries(s.by_type).sort((a, b) => b[1] - a[1]).map(([t, n], i) => U.rankRow(A.TYPE[t], n / mx, U.fmt(n), i)).join('')}</section>
      <section class="card plus" data-api="GET /api/events?limit=6 (poll 3 s)"><h2 class="h3">Latest requests</h2><table class="tbl"><tbody>${ev.length ? '' : '<tr><td class="muted">No requests yet.</td></tr>'}${ev.slice(0, 6).map((e) => `<tr><td>${e.source} → ${e.sink}</td><td class="num mono">${e.findings.length} found</td><td class="num muted">${U.ago(e.at)}</td></tr>`).join('')}</tbody></table><div style="margin-top:12px"><a class="btn ghost" href="#traffic">Open live traffic →</a></div></section></div>
      <section class="card plus ${s.open_alerts ? 'danger' : ''}" style="margin-top:16px" data-api="GET /api/immune → alerts (top 3, poll 4 s)"><h2 class="h3">Latest immune alerts</h2>${A.alerts.length ? '' : `<p class="muted">No alerts. Mode: ${s.immune.mode}.</p>`}${A.alerts.slice(0, 3).map((a) => `<div class="between" style="padding:6px 0"><span><i style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--leak-color);margin-right:10px"></i>${a.src} → ${a.sink}: ${a.reasons[0]}</span></div>`).join('')}<div style="margin-top:12px"><a class="btn ghost" href="#immune">Open immune layer →</a></div></section>`;
    },
    mount: (root) => {
      U.runCounts(root); const re = () => { root.innerHTML = P.overview.view(); U.setCounts(root); U.keepTip(); };
      /* the first-run buttons: real requests through the live firewall, then the page refreshes itself */
      const onClick = async (e) => {
        const b = e.target.closest('[data-ov]'); if (!b || b.disabled) return;
        b.disabled = true; b.classList.add('busy');
        try {
          if (b.dataset.ov === 'send') { for (const k of ['kyc', 'loan', 'callnote', 'payment', 'otp', 'chatbot']) await A.sample(k); U.toast('6 requests protected'); }
          else { await A.replay(true, 2); U.toast('Normal traffic replay started'); }
          await A.refresh('stats', 'events');
        } catch (err) { U.toast('Could not reach the server: ' + err.message); b.disabled = false; b.classList.remove('busy'); }
      };
      root.addEventListener('click', onClick);
      const offs = ['stats', 'events', 'immune'].map((k) => A.on(k, re));
      return () => { offs.forEach((f) => f()); root.removeEventListener('click', onClick); };
    },
  };

  /* ============================================================ 3 Live traffic */
  P.traffic = {
    eyebrow: 'LIVE TRAFFIC', title: 'Send a request through Aran', lede: 'Pick a bank request or paste your own text. Aran detects every sensitive value, replaces it before it reaches the sink, and shows its reasoning.',
    view: () => `<div class="card plus" data-api="GET /api/config · POST /api/sample · POST /api/process"><div class="tabs" role="tablist"><button class="tab" role="tab" data-tab="sample" aria-selected="true">Bank requests</button><button class="tab" role="tab" data-tab="own" aria-selected="false">Your own text</button></div>
      <div data-panel="sample"><div class="seg" role="radiogroup" aria-label="Who"><label><input type="radio" name="who" value="customer" checked><span>Enrolled customer (registry knows them)</span></label><label><input type="radio" name="who" value="stranger"><span>Stranger (not in the registry)</span></label></div><div class="btn-grid">${Object.entries(A.SAMPLES).map(([k, [l, s, d]]) => `<button class="btn tile" data-k="${k}">${l}<span class="s">${s} → ${d}</span></button>`).join('')}</div></div>
      <div data-panel="own" class="hidden"><div class="row" style="margin-bottom:8px;justify-content:flex-end"><button class="btn secondary sm" id="tx-sample-btn" type="button">Insert a valid sample</button></div><textarea class="mono" id="tx-text" maxlength="20000" placeholder="Paste a log line, JSON body or chat prompt. Use generated test numbers only, never a real person’s."></textarea><div class="counter"><span id="tx-n">0</span> / 20,000</div><div class="row"><label class="field">Source<input id="tx-src" value="my-app"></label><label class="field">Customer ref (optional)<input id="tx-cust" placeholder="e.g. CUST-0001" maxlength="64"></label><label class="field">Sink<select id="tx-sink">${A.SINKS.map((s) => `<option value="${s.name}">${s.name} (${s.purpose})</option>`).join('')}</select></label><button class="btn" id="tx-go" disabled><span>Protect</span><span class="arr">→</span></button></div></div><div id="tx-err"></div></div>
      <div id="tx-res" style="margin-top:24px"></div>
      <section class="card plus" style="margin-top:16px" data-api="GET /api/events?limit=15 (poll 4 s)"><h2 class="h3">Recent traffic on this server</h2><div class="scroll"><table class="tbl"><thead><tr><th>When</th><th>Flow</th><th class="num">Found</th><th class="num">Latency</th></tr></thead><tbody id="tx-recent"></tbody></table></div></section>`,
    mount(root) {
      let ev = A.events[0], pick = null; U.tabs(root);
      const recent = () => ($('#tx-recent', root).innerHTML = A.events.slice(0, 15).map((e, i) => `<tr class="click ${ev && e.id === ev.id ? 'sel' : ''}" data-i="${i}"><td class="muted">${U.ago(e.at)}</td><td>${e.source} → ${e.sink}</td><td class="num mono">${e.findings.length}</td><td class="num mono">${e.latency_ms} ms</td></tr>`).join('') || '<tr><td colspan="4" class="muted">No traffic yet.</td></tr>');
      const show = () => {
        if (!ev) { $('#tx-res', root).innerHTML = ''; return; } const thr = (A.SINKS.find((s) => s.name === ev.sink) || {}).threshold || 0.5, f = pick != null ? ev.findings[pick] : null;
        $('#tx-res', root).innerHTML = `<div class="between" style="margin-bottom:12px"><span><b>${ev.source}</b> → <b>${ev.sink}</b> ${ev.bypass ? U.pill('monitor-only', 'danger') : ''}</span><span class="mono small muted">${ev.findings.length} found · ${ev.latency_ms} ms · ${U.ago(ev.at)}</span></div>
        <div class="grid g2"><section class="card plus"><h2 class="h3">Before (what the app sent)</h2>${U.marked(ev.before, ev.findings, pick)}<div class="small muted" style="margin-top:8px">Click a highlighted value to see why it was caught.</div></section><section class="card plus"><h2 class="h3">After (what ${ev.sink} stored)</h2><div style="animation:fade .6s .35s both">${U.tokenText(ev.after, ev.findings)}</div></section></div>
        ${f ? `<section class="card plus" style="margin-top:16px;animation:pop .35s both"><h2 class="h3">Why the detector flagged this ${A.TYPE[f.type]}</h2><div class="between"><span>Calibrated probability</span><b class="mono">${U.pct(f.p)}</b></div>${U.bar(f.p, thr)}<div class="small muted">Marker = this sink’s threshold (${thr}). At or above it the value is replaced.</div><table class="tbl dense" style="margin-top:12px"><tbody>${Object.entries(f.evidence).map(([k, v]) => `<tr><td>${A.EVIDENCE[k] || k}</td><td class="num mono">${v}</td></tr>`).join('')}${f.registry ? '<tr><td>Own-customer / OTP registry</td><td class="num mono">hit</td></tr>' : ''}${f.repaired ? '<tr><td>Typo repaired to a registered customer</td><td class="num mono">yes</td></tr>' : ''}</tbody></table><div class="small muted" style="margin-top:12px">Result: ${f.protected ? `replaced by <code>${U.esc(f.token)}</code>` : 'below threshold, passed raw'}</div></section>` : ''}
        <section class="card plus" style="margin-top:16px"><h2 class="h3">Findings</h2>${ev.findings.length === 0 ? '<p class="muted">Nothing sensitive found.</p>' : `<div class="scroll"><table class="tbl"><thead><tr><th>Type</th><th>Value</th><th>Became</th><th>Protection</th><th class="num">Confidence</th><th>Registry</th></tr></thead><tbody>${ev.findings.map((x, i) => `<tr class="click ${pick === i ? 'sel' : ''}" data-f="${i}"><td>${A.TYPE[x.type]}</td><td class="mono">${U.esc(ev.before.slice(x.start, x.end))}</td><td class="mono">${x.protected ? U.esc(x.token || '–') : U.pill('passed raw', 'danger')}</td><td>${x.protected ? (x.erasable ? U.pill('Erasable (vault token)', 'ok') : U.pill('Traceable only (vaultless)', 'warn')) : '–'}</td><td class="num mono">${U.pct(x.p)}</td><td>${x.registry || '–'}</td></tr>`).join('')}</tbody></table></div>`}</section>
        ${ev.notes && ev.notes.length ? `<div style="margin-top:16px">${ev.notes.map((n) => U.note('warn', U.esc(n))).join('')}</div>` : ''}`;
        $$('mark[data-i]', root).forEach((m) => (m.onclick = () => { pick = +m.dataset.i; show(); })); $$('tr[data-f]', root).forEach((r) => (r.onclick = () => { pick = +r.dataset.f; show(); }));
      };
      const run = async (p) => { let e; try { $('#tx-err', root).innerHTML = ''; e = await p; } catch (x) { $('#tx-err', root).innerHTML = U.note('err', U.esc(x.message)); A.sound.error(); return; } ev = e; pick = null; A.events = [e].concat(A.events.filter((x) => x.id !== e.id)); show(); recent(); A.sound.click(); A.refresh('stats', 'events'); };
      $$('.tile', root).forEach((b) => (b.onclick = async () => { $$('.tile', root).forEach((x) => (x.disabled = true)); await run(A.sample(b.dataset.k, $('input[name="who"]:checked', root).value)); $$('.tile', root).forEach((x) => (x.disabled = false)); }));
      const t = $('#tx-text', root); t.oninput = () => { $('#tx-n', root).textContent = U.fmt(t.value.length); $('#tx-go', root).disabled = !t.value.trim(); };
      const bSample = $('#tx-sample-btn', root);
      if (bSample) {
        bSample.onclick = async () => {
          try {
            const g = await A.generate();
            t.value = `Aadhaar number is ${g.aadhaar}`;
            $('#tx-n', root).textContent = U.fmt(t.value.length);
            $('#tx-go', root).disabled = false;
            A.sound.click();
          } catch (e) {
            U.toast(e.message);
          }
        };
      }
      $('#tx-go', root).onclick = () => { const sink = $('#tx-sink', root).value; if (!/^[a-z0-9.-]+$/.test(sink)) { $('#tx-err', root).innerHTML = U.note('err', 'sink names are lower-case letters, digits, dots and dashes'); return; } const cust = ($('#tx-cust', root)?.value || '').trim(); run(A.api('/process', { text: t.value, source: $('#tx-src', root).value || 'console', sink, ...(cust ? { customer_ref: cust } : {}) })); };
      $('#tx-recent', root).onclick = (e) => { const tr = e.target.closest('tr[data-i]'); if (tr) { ev = A.events[+tr.dataset.i]; pick = null; show(); recent(); } };
      show(); recent(); return A.on('events', recent); } };

  /* ============================================================ 4 Customers and erasure */
  P.customers = {
    eyebrow: 'PURPOSE-BOUND CRYPTO-SHREDDING (M5)', title: 'Destroy one key. Every copy is erased, with a signed receipt.', lede: 'Each customer has one key per purpose. Tokens sent to sinks are encrypted under that key. Destroy the key and every token for that purpose, in every log and vendor copy, can never be read again.',
    view: () => `<div class="grid g-side"><section class="card plus" data-api="GET /api/customers"><div class="between"><h2 class="h3">Customers</h2><button class="btn ghost sm" id="cu-add">+ Add</button></div><p class="small muted">Generated identities. Identifiers are checksum-valid but belong to no one.</p><input id="cu-q" placeholder="Search customers" aria-label="Search customers" style="width:100%;margin-top:12px"><div class="list" id="cu-list"></div></section><section id="cu-detail" class="stack"></section></div><section class="card plus" style="margin-top:16px" data-api="GET /api/merkle"><h2 class="h3">Transparency log</h2><div class="small muted mono" id="cu-mroot"></div><div class="scroll"><table class="tbl dense"><thead><tr><th>Event</th><th>Customer</th><th>Purpose</th><th>When</th></tr></thead><tbody id="cu-log"></tbody></table></div></section>`,
    mount(root) {
      let sel = null, cur = null, receipt = null, check = null, detok = null; const rcs = {};
      /* the list polls: when the same customers are shown, only their counts and the selection are
         updated in place, so a button never disappears under the mouse; a new set redraws the list */
      const list = () => {
        const q = $('#cu-q', root).value.toLowerCase(), box = $('#cu-list', root);
        const rows = A.customers.filter((c) => (c.ref + c.name).toLowerCase().includes(q)).map((c) => { const gone = c.keys.filter((k) => !k.alive).length; return { c, n: gone ? gone + ' erased' : c.keys.reduce((a, k) => a + k.tokens, 0) + ' tokens' }; });
        const btns = [...box.querySelectorAll('button.li')];
        if (rows.length && btns.length === rows.length && btns.every((b, k) => b.dataset.ref === rows[k].c.ref)) {
          btns.forEach((b, k) => { b.classList.toggle('on', sel === rows[k].c.ref); const m = b.lastElementChild; if (m.textContent !== rows[k].n) m.textContent = rows[k].n; });
          return;
        }
        box.innerHTML = rows.map(({ c, n }) => `<button class="li ${sel === c.ref ? 'on' : ''}" data-ref="${c.ref}"><span><b class="mono">${c.ref}</b> ${U.esc(U.person(c.name))}</span><span class="small muted">${n}</span></button>`).join('') || '<p class="muted small" style="padding:12px 0">No match.</p>';
      };
      const log = (fresh) => { const M = A.merkle; $('#cu-mroot', root).textContent = `${M.size} entries · root ${String(M.root).slice(0, 32)}…`; U.patch($('#cu-log', root), M.recent.slice(0, 10).map((e, i) => `<tr style="${fresh && i === 0 ? 'animation:rise .5s both' : ''}"><td class="${e.event === 'KEY_DESTROYED' ? 't-leak' : ''}">${e.event}</td><td class="mono">${e.customer}</td><td>${e.purpose || '–'}</td><td class="muted">${U.ago(e.at)}</td></tr>`).join('')); };
      const load = async () => { if (!sel) { cur = null; return; } try { cur = await A.customer(sel); } catch (e) { cur = null; U.toast(e.message); } };
      const detail = () => {
        const d = $('#cu-detail', root), c = cur;
        if (!c) { d.innerHTML = `<div class="card muted">Pick a customer to see their keys and erase a purpose. Send some bank requests first so they have tokens in the sinks.</div>`; return; }
        const keys = `<div class="card plus" data-api="GET /api/customers/{ref}"><h2 class="h3">${c.ref} · ${U.esc(U.person(c.name))}</h2><div class="chips">${Object.entries(c.masked).map(([k, v]) => `<span class="chip mono">${k} ${v}</span>`).join('')}</div><div class="scroll"><table class="tbl"><thead><tr><th>Purpose</th><th>Key</th><th class="num">Tokens</th><th class="num">Action</th></tr></thead><tbody>${c.keys.map((k) => `<tr><td>${k.purpose}</td><td>${k.alive ? U.pill('alive', 'ok') : U.pill('destroyed', 'danger')}</td><td class="num mono">${k.tokens}</td><td class="num">${k.alive ? (k.locked_until ? `<span class="small t-warn" data-tip="PMLA: KYC records are kept 5 years">🔒 locked until ${new Date(k.locked_until * 1000).toLocaleDateString()}</span>` : `<button class="btn danger sm" data-erase="${k.purpose}">Erase</button>`) : (k.receipt || rcs[c.ref + k.purpose]) ? `<button class="btn ghost sm" data-rc="${k.purpose}">Receipt</button>` : ''}</td></tr>`).join('')}</tbody></table></div><div id="cu-err"></div></div>`;
        const rc = receipt ? `<div class="card receipt plus" data-api="POST /api/erase · POST /api/receipts/verify"><h2 class="h3">Erasure receipt</h2><table class="tbl dense"><tbody><tr><td>Customer</td><td class="mono">${receipt.event.customer}</td></tr><tr><td>Purpose</td><td>${receipt.event.purpose}</td></tr><tr><td>Tokens made unreadable</td><td class="mono">${receipt.event.tokens_unreadable}</td></tr><tr><td>Signed at</td><td>${new Date(receipt.event.at * 1000).toLocaleString()}</td></tr><tr><td>Merkle leaf / tree size</td><td class="mono">${receipt.leaf_index} / ${receipt.tree_size}</td></tr><tr><td>Merkle root</td><td class="mono trunc" data-tip="${A.b64hex(receipt.root)}">${A.b64hex(receipt.root)}</td></tr><tr><td>Signature (Ed25519)</td><td class="mono trunc">${receipt.signature}</td></tr><tr><td>Post-quantum signature (ML-DSA-65)</td><td class="mono trunc">${receipt.pq_signature || '–'}</td></tr></tbody></table>${check ? `<div class="mchain">${check.chain.map((h, i) => `<div class="mh on"><span>${i === 0 ? 'erasure' : i === check.chain.length - 1 ? 'root' : 'level ' + i}</span>${h.slice(0, 10)}</div>`).join('')}</div><p class="small muted">${check.ok ? '✓ Your browser re-ran the inclusion proof up to the signed root.' : '✗ The inclusion proof did not reach the signed root in this browser.'}</p>` : ''}<div class="row"><button class="btn sm" id="rc-v">Verify receipt</button><button class="btn secondary sm" id="rc-t">Try tampering with it</button><button class="btn ghost sm" id="rc-c">Copy JSON</button></div><div id="rc-out"></div></div>` : '';
        const toks = `<div class="card plus" data-api="POST /api/detokenise"><h2 class="h3">Try to read a token back</h2><p class="small muted">Detokenisation is logged per caller. After erasure it fails for good.</p><div class="chips">${(c.tokens || []).slice(-6).map((t) => `<button class="chip mono" data-tok="${U.esc(t.token)}">${U.esc(t.token)} <span class="muted">${t.sink}</span></button>`).join('') || '<span class="small muted">No tokens yet. Send a bank request for this customer.</span>'}</div><div class="row"><input class="mono grow" id="dt-in" placeholder="token" aria-label="Token"><button class="btn secondary" id="dt-go" disabled>Detokenise</button></div><div id="dt-out">${detok || ''}</div></div>`;
        d.innerHTML = keys + rc + toks;
        $$('[data-erase]', d).forEach((b) => (b.onclick = async () => { const p = b.dataset.erase; const ok = await U.confirm({ title: `Destroy ${c.ref}’s ${p} key?`, body: `Every ${p} token for this customer becomes permanently unreadable.`, confirmLabel: 'Destroy key' }); if (!ok) return; try { receipt = await A.erase(c.ref, p); rcs[c.ref + p] = receipt; check = await A.browserInclusion(receipt).catch(() => null); A.sound.shatter(); await Promise.all([load(), A.refresh('customers', 'merkle', 'stats')]); list(); detail(); log(true); } catch (e) { $('#cu-err', d).innerHTML = U.note('err', U.esc(e.message)); A.sound.error(); } }));
        $$('[data-rc]', d).forEach((b) => (b.onclick = async () => { const k = c.keys.find((x) => x.purpose === b.dataset.rc); receipt = (k && k.receipt) || rcs[c.ref + b.dataset.rc]; check = receipt ? await A.browserInclusion(receipt).catch(() => null) : null; detail(); }));
        const v = $('#rc-v', d);
        if (v) {
          const out = (r, what) => U.note(r.valid ? 'ok' : 'err', what + ': ' + (r.signature_valid ? (r.post_quantum_valid ? 'Ed25519 and ML-DSA-65 signatures valid' : 'Ed25519 signature valid') : 'signature invalid') + ', ' + (r.included_in_log ? 'included in the signed Merkle root.' : 'not in the log.'));
          v.onclick = async () => { try { $('#rc-out', d).innerHTML = out(await A.verify(receipt), 'Server check'); } catch (e) { $('#rc-out', d).innerHTML = U.note('err', U.esc(e.message)); } };
          $('#rc-t', d).onclick = async () => { const t = JSON.parse(JSON.stringify(receipt)); t.event.tokens_unreadable += 1; try { const r = await A.verify(t); $('#rc-out', d).innerHTML = r.valid ? U.note('err', 'The edited copy still verified. That should not happen.') : U.note('ok', `Changing one number (tokens made unreadable ${receipt.event.tokens_unreadable} → ${t.event.tokens_unreadable}) broke it: ${r.signature_valid ? '' : 'signature invalid, '}${r.included_in_log ? 'inclusion still valid' : 'inclusion invalid'}.`); } catch (e) { $('#rc-out', d).innerHTML = U.note('err', U.esc(e.message)); } };
          $('#rc-c', d).onclick = () => { navigator.clipboard && navigator.clipboard.writeText(JSON.stringify(receipt, null, 1)); U.toast('Copied'); };
        }
        const inp = $('#dt-in', d); inp.oninput = () => ($('#dt-go', d).disabled = !inp.value.trim());
        const tryTok = async (t) => { try { const r = await A.detokenise(t.trim()); detok = r.status === 'ok' ? U.note('ok', `Value: <code>${U.esc(r.value)}</code>`) : U.note('err', U.esc(r.reason || r.status)); A.refresh('immune'); } catch (e) { detok = U.note('err', U.esc(e.message)); } $('#dt-out', d).innerHTML = detok; };
        $$('[data-tok]', d).forEach((b) => (b.onclick = () => { inp.value = b.dataset.tok; $('#dt-go', d).disabled = false; tryTok(b.dataset.tok); })); $('#dt-go', d).onclick = () => tryTok(inp.value);
      };
      $('#cu-list', root).onclick = async (e) => { const b = e.target.closest('[data-ref]'); if (b) { sel = b.dataset.ref; receipt = null; check = null; detok = null; list(); await load(); detail(); } };
      $('#cu-q', root).oninput = list;
      $('#cu-add', root).onclick = async () => { try { const n = await A.addCustomer(); await A.refresh('customers', 'merkle'); sel = n.ref; receipt = null; check = null; detok = null; await load(); list(); detail(); log(true); } catch (e) { U.toast(e.message); } };
      list(); detail(); log();
      const offs = [A.on('customers', list), A.on('merkle', () => log())]; return () => offs.forEach((f) => f()); } };

  /* ============================================================ 5 Leak trace */
  P.trace = {
    eyebrow: 'LEAK ATTRIBUTION (M3)', title: 'A leaked token names the system that leaked it.', lede: 'Every sink receives different tokens for the same customer. Paste a leaked file and Aran tells you which sink it came from, with the evidence.',
    view: () => `<div class="card plus" data-api="GET /api/config · GET /api/leaked-dump?sink={name}&lines=20 · POST /api/trace"><div class="row"><label class="field">Take what this sink really stored<select id="tr-sink">${A.SINKS.map((s) => `<option>${s.name}</option>`).join('')}</select></label><button class="btn secondary" id="tr-load">Load its last 20 lines</button></div><textarea class="mono" id="tr-dump" rows="8" maxlength="200000" placeholder="Paste a leaked dump, or load one from a sink above. You can mix lines from several sinks."></textarea><div class="counter"><span id="tr-n">0</span> / 200,000 · drop a .txt or .log file here</div><div class="row"><button class="btn" id="tr-go" disabled><span>Trace the leak</span><span class="arr">→</span></button></div><div id="tr-err"></div></div><div id="tr-res" style="margin-top:16px"></div>`,
    mount(root) {
      const ta = $('#tr-dump', root), go = $('#tr-go', root), upd = () => { $('#tr-n', root).textContent = U.fmt(ta.value.length); go.disabled = !ta.value.trim(); }; ta.oninput = upd;
      $('#tr-load', root).onclick = async () => { const s = $('#tr-sink', root).value; $('#tr-res', root).innerHTML = ''; try { const d = await A.leakedDump(s, 20); if (!d.dump.trim()) { $('#tr-err', root).innerHTML = U.note('err', `${s} has not received anything yet. Send some traffic to it first.`); ta.value = ''; upd(); return; } $('#tr-err', root).innerHTML = ''; ta.value = d.dump; upd(); } catch (e) { $('#tr-err', root).innerHTML = U.note('err', U.esc(e.message)); } };
      ['dragenter', 'dragover'].forEach((e) => ta.addEventListener(e, (ev) => { ev.preventDefault(); ta.classList.add('invalid'); ta.style.borderStyle = 'dashed'; }));
      ['dragleave', 'drop'].forEach((e) => ta.addEventListener(e, () => { ta.classList.remove('invalid'); ta.style.borderStyle = ''; }));
      ta.addEventListener('drop', (ev) => { ev.preventDefault(); const f = ev.dataTransfer.files[0]; if (f) f.text().then((t) => { ta.value = t.slice(0, 200000); upd(); }); });
      go.onclick = async () => {
        go.classList.add('busy'); go.firstElementChild.textContent = 'Tracing…'; let r;
        try { r = await A.trace(ta.value); $('#tr-err', root).innerHTML = ''; } catch (e) { $('#tr-err', root).innerHTML = U.note('err', U.esc(e.message)); A.sound.error(); }
        go.classList.remove('busy'); go.firstElementChild.innerHTML = 'Trace the leak'; if (!r) return;
        const rank = r.ranking || [], raw = r.raw_identifiers_in_dump || 0;
        $('#tr-res', root).innerHTML = `<div class="grid g2"><section class="card plus" style="animation:pop .4s both"><h2 class="h3">${rank[0] ? `Most likely source: <span class="t-accent">${rank[0].sink}</span>` : 'No Aran tokens found'}</h2><p class="small muted">${r.matched} of ${r.candidates} candidate values matched a token issued by this server.${raw ? ` <b class="t-leak">${raw} raw identifier${raw === 1 ? '' : 's'}</b> in the dump ${raw === 1 ? 'was' : 'were'} never tokenised, so ${raw === 1 ? 'it' : 'they'} leaked before Aran or through a bypass.` : ''}</p>${rank.map((x, i) => U.rankRow(x.sink, x.share, `${x.tokens} · ${Math.round(x.share * 100)}%`, i)).join('')}</section><section class="card plus" style="animation:pop .4s .1s both"><h2 class="h3">Evidence per value</h2><div class="scroll"><table class="tbl dense"><thead><tr><th>Value</th><th>Sink</th><th>How</th></tr></thead><tbody>${(r.items || []).slice(0, 60).map((x) => `<tr><td class="mono">${U.esc(x.value)}</td><td>${x.sink || '<span class="muted">no match</span>'}</td><td class="muted">${x.how || '–'}</td></tr>`).join('')}</tbody></table></div></section></div>`; A.sound.chime(); };
      upd(); } };

  /* ============================================================ 6 Immune layer */
  P.immune = {
    eyebrow: 'ARTIFICIAL IMMUNE SYSTEM', title: 'Learns what normal looks like, then flags what is not.', lede: 'Every 30 seconds the firewall closes one flow record per source and sink: how many messages carried sensitive values, how many left raw, which data classes, how often tokens were read back. The immune layer learns “self” from this server’s own traffic, then scores every new record with negative selection.',
    view: () => `<div class="grid g4" id="im-stats" data-api="GET /api/immune → state · GET /api/stats → replay"></div>
      <section class="card plus" style="margin-top:16px"><span class="label">Live radar · GET /api/tour/immune-radar</span><div id="ip-radar"></div></section>
      <div class="grid g2" style="margin-top:16px"><section class="card plus"><h2 class="h3">1. Normal traffic</h2><p class="small muted">Replays real production log lines (Loghub, 16 systems) through the firewall as the bank’s everyday traffic. About one line in ten carries a bank event for an enrolled customer.</p><div class="row"><label class="field">Lines per second per flow<input type="number" id="rate" min="0.2" max="5" step="0.2" value="1"></label><button class="btn" id="rep"><span>Stop replay</span></button></div><div class="small muted" id="rep-s"></div></section>
      <section class="card plus"><h2 class="h3">2. Learn self</h2><p class="small muted">Starts the replay if needed, collects flow records for the chosen time, then fits the detectors with the self radius tuned on held-out windows.</p><div class="row"><label class="field">Seconds<input type="number" id="secs" min="30" max="1800" value="360"></label><button class="btn" id="learn"><span>Re-learn</span></button></div><div class="small muted" id="self-pairs"></div></section></div>
      <section class="card plus" style="margin-top:16px"><h2 class="h3">3. Run a drill</h2><p class="small muted">Each drill performs a real action on the live firewall. The immune layer is not told about it; it has to notice the flow window on its own when the window closes (up to 30s). <b class="mono" id="cd"></b></p><div class="btn-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${Object.entries(A.DRILLS).map(([k, l]) => `<button class="btn tile" data-drill="${k}">⚡ ${l}</button>`).join('')}</div><div class="small muted" id="dr-hint"></div><div id="dr-msg"></div></section>
      <section class="block"><div class="sechead"><h2 class="h3">Alerts</h2><div class="chips" id="al-f" style="margin:0">${['All', 'Open', 'Confirmed', 'Normal'].map((f, i) => U.chip(f, { btn: true, on: !i, attrs: `data-f="${f}"` })).join('')}</div></div><div id="al-list"></div></section>`,
    mount(root) {
      let r = null, filter = 'All', total = 0, shape = '', timer = null, alive = true;
      const st = () => (r && r.state) || A.immune.state || {}, mode = () => (r ? r.mode : st().mode);
      const stats = () => { const s = st(), m = mode(); $('#im-stats', root).innerHTML = U.stat('Mode', `<span class="word ${m === 'learning' ? 't-warn' : m === 'watching' ? 't-ok' : ''}">${m}</span>`, m === 'learning' ? `${r && r.learn_left != null ? r.learn_left : '…'}s left` : m === 'watching' ? `learned from ${U.fmt(s.learned_records)} records` : s.error ? U.esc(s.error) : 'not trained yet') + U.stat('Detectors', m === 'watching' ? U.fmt(s.detectors) : '–', m === 'watching' ? `self radius ${s.self_radius}` : '–') + U.stat('Held-out false alarms', m === 'watching' && s.val_fpr != null ? (s.val_fpr * 100).toFixed(1) + '%' : '–', 'on normal windows it did not train on') + U.stat('Flow windows', U.fmt(A.immune.closed_windows), `${A.immune.open_windows || 0} open now`); $('#self-pairs', root).textContent = s.pairs ? 'Self covers: ' + s.pairs.join(', ') : ''; };
      const radar = () => {
        const el = $('#ip-radar', root), m = mode(); if (!r) return; if (m === 'learning') total = Math.max(total, r.learn_left || 0);
        if (shape !== m) { shape = m; el.innerHTML = m === 'watching' ? `<div class="radarwrap"><div id="ip-svg"></div><div class="stack">${legend}<div class="small muted">Next check in <b class="mono" id="ip-next"></b> · <span id="ip-det"></span> detectors</div></div></div>` : m === 'learning' ? `<div class="learn"><div id="ip-ring"></div><div><h2 class="h3">Learning what “normal” looks like…</h2><p class="muted">Real log lines are flowing through the firewall right now.</p></div></div>` : `<div class="learn"><div class="pulse">?</div><div><h2 class="h3">Not trained yet.</h2><p class="muted">Press “Learn” below to teach it.</p></div></div>`; }
        if (m === 'watching') { $('#ip-svg', el).innerHTML = A.radarSVG(r.windows.slice().reverse()); $('#ip-next', el).textContent = Math.round(r.next_window_in) + 's'; $('#ip-det', el).textContent = st().detectors; }
        if (m === 'learning') $('#ip-ring', el).innerHTML = ring(total ? 1 - (r.learn_left || 0) / total : 0, clock(r.learn_left || 0));
      };
      const rep = () => { const p = A.stats.replay || {}, b = $('#rep', root); b.firstElementChild.textContent = p.running ? 'Stop replay' : 'Start replay'; b.className = 'btn ' + (p.running ? 'secondary' : ''); $('#rep-s', root).innerHTML = `${p.running ? '<span class="t-ok">● Running</span>' : 'Stopped'} · ${U.fmt(p.lines_sent)} lines sent · flows: ${(p.flows || []).join(', ')}`; };
      const drills = () => {
        const m = mode();
        $$('[data-drill]', root).forEach((b) => (b.disabled = m !== 'watching'));
        if (m === 'learning') {
          const left = r && r.learn_left != null ? Math.round(r.learn_left) : '…';
          $('#dr-hint', root).textContent = `Learning, ready in ${left} s`;
        } else if (m !== 'watching') {
          $('#dr-hint', root).textContent = 'Available once the immune layer has learned normal traffic.';
        } else {
          $('#dr-hint', root).textContent = '';
        }
        $('#cd', root).textContent = r ? `Next window closes in ${Math.round(r.next_window_in)}s` : '';
      };
      let lastAl = '';
      const al = () => { const l = A.alerts.filter((a) => filter === 'All' || (filter === 'Open' && !a.label) || (filter === 'Confirmed' && a.label === 'attack') || (filter === 'Normal' && a.label === 'normal')); const k = filter + l.map((a) => a.id + a.label).join(); if (k === lastAl) return; lastAl = k; $('#al-list', root).innerHTML = l.length ? l.map((a) => alertBox(a)).join('') : '<p class="muted">No alerts.</p>'; $$('[data-lab]', root).forEach((b) => (b.onclick = async () => { b.disabled = true; await A.labelAlert(b.dataset.id, b.dataset.lab); al(); })); };
      const all = () => { stats(); radar(); rep(); drills(); al(); };
      const tick = async () => { try { const [x] = await Promise.all([A.radar(), A.refresh('immune', 'stats')]); if (!alive) return; r = x; A.lastWindows = x.windows.slice().reverse(); all(); } catch (e) { $('#ip-radar', root).innerHTML = U.note('err', U.esc(e.message)); shape = ''; } };
      $('#rep', root).onclick = async () => { try { await A.replay(!(A.stats.replay || {}).running, +$('#rate', root).value || 1); await A.refresh('stats'); rep(); } catch (e) { U.toast(e.message); } };
      $('#learn', root).onclick = async () => { try { await A.learn(+$('#secs', root).value || 360); total = 0; await tick(); A.sound.click(); } catch (e) { U.toast(e.message); } };
      $$('[data-drill]', root).forEach((b) => (b.onclick = async () => { b.disabled = true; try { const d = await A.drill(b.dataset.drill); $('#dr-msg', root).innerHTML = U.note('ok', `${U.esc(d.done)} The immune layer was not told; watch the alerts below when the window closes (up to ${d.window_seconds}s).`); A.sound.error(); } catch (e) { $('#dr-msg', root).innerHTML = U.note('err', U.esc(e.message)); } b.disabled = false; }));
      $('#al-f', root).onclick = (e) => { const c = e.target.closest('[data-f]'); if (!c) return; filter = c.dataset.f; $$('#al-f .chip', root).forEach((x) => x.classList.toggle('on', x === c)); al(); };
      all(); tick(); timer = setInterval(tick, 2000); return () => { alive = false; clearInterval(timer); }; } };

  /* ============================================================ 7 Results and tests */
  const heat = (v) => `color-mix(in srgb, var(--success-color) ${Math.round(v * 100)}%, var(--leak-color))`;
  P.results = {
    eyebrow: 'EVIDENCE', title: 'Results from the experiment scripts, not from slides', lede: 'These tables are read from the result files the experiment scripts wrote. Run the test suite or re-run E1 to E4 on this server and watch the output.',
    view() {
      const R = A.results || {}, c = R.core, a = R.ai, g = R.reg, f = (n) => `${(n * 100).toFixed(1)}%`, mod = (m) => new Date(m * 1000).toLocaleString();
      const job = (id, label, note) => `<section class="card plus" data-job="${id}" data-api="POST /api/jobs/${id} · GET /api/jobs/${id} (poll 2 s)"><div class="between"><h2 class="h3">${label}</h2><button class="btn" data-run><span>Run now</span></button></div><p class="small muted">${note}</p><div class="small" data-status></div><pre class="logline mono out hidden" data-out></pre></section>`;
      const jobs = `<div class="grid g2">${job('tests', 'Run the test suite', 'pytest: NIST FF1 vectors, Verhoeff and Luhn, token invariants, normaliser, registries, crypto-shredding and Merkle receipts.')}${job('e1-e4', 'Re-run experiments E1 to E4', 'False alarms on 32,000 real Loghub lines, token separability, leak attribution, mask leakage. Takes a few minutes; the table below updates when it finishes.')}</div>`;
      if (!c || !a || !g) return jobs + `<div style="margin-top:16px">${U.note('info', 'Some result files are missing on this server. Run the experiments to create them.')}</div>`;
      return jobs + `
      <section class="card plus" style="margin-top:16px" data-api="GET /api/results → E1-E4 core"><h2 class="h3">E1 to E3 on ${U.fmt(c.e1.lines)} real production log lines <span class="small muted">(${c.file}, written ${mod(c.modified)})</span></h2><div class="scroll"><table class="tbl"><thead><tr><th>Test</th><th class="num">Plain pattern matching</th><th class="num">Aran</th></tr></thead><tbody><tr><td>OTP false alarms</td><td class="num mono">${U.fmt(c.e1.otp_regex)}</td><td class="num mono">${c.e1.otp_context}</td></tr><tr><td>Card false alarms (Luhn + issuer prefix)</td><td class="num mono">${U.fmt(c.e1.card_regex)}</td><td class="num mono">${c.e1.card_luhn_iin}</td></tr><tr><td>Aadhaar false alarms (Verhoeff)</td><td class="num mono">${c.e1.aadhaar_regex}</td><td class="num mono">${c.e1.aadhaar_verhoeff}</td></tr><tr><td>Tokens wrongly flagged as real (of ${U.fmt(c.e2.injected)})</td><td class="num">not separable</td><td class="num mono">${c.e2.token_flagged}</td></tr><tr><td>Leaked dumps traced to the right sink (${c.e3.sinks} sinks, 1 token)</td><td class="num">access logs only</td><td class="num mono">${Math.round(c.e3.dump_1_accuracy * 100)}%</td></tr></tbody></table></div>
      <h2 class="h3" style="margin-top:32px">E4: what common masks still leave</h2><div class="scroll"><table class="tbl"><thead><tr><th>Mask</th><th class="num">Candidates left</th><th class="num">Bits left</th><th style="width:30%"><span class="sr-only">Bits left, as a bar</span></th></tr></thead><tbody>${c.e4.map((m) => `<tr><td>${m.mask}</td><td class="num mono">${typeof m.candidates === 'number' ? U.fmt(m.candidates) : m.candidates}</td><td class="num mono">${m.bits_left}</td><td><div class="bar" style="margin:6px 0"><i style="width:${Math.max(1, (m.bits_left / 24) * 100)}%"></i></div></td></tr>`).join('')}</tbody></table></div></section>
      <section class="card plus" style="margin-top:16px" data-api="GET /api/results → E5-E9 AI and immune"><h2 class="h3">E9: the wired firewall on ${U.fmt(a.e9.lines)} real lines of unseen systems</h2><div class="scroll"><table class="tbl"><thead><tr><th>Test</th><th class="num">Prototype regex</th><th class="num">Aran with AI layers</th></tr></thead><tbody><tr><td>Sensitive values removed</td><td class="num mono">${f(a.e9.prototype_regex_recall)}</td><td class="num mono">${f(a.e9.leak_recall)}</td></tr><tr><td>Clean real lines wrongly changed${a.e9.clean_of ? ` (of ${U.fmt(+a.e9.clean_of)})` : ''}</td><td class="num mono">${U.fmt(a.e9.prototype_clean_lines_flagged)}</td><td class="num mono">${U.fmt(a.e9.clean_real_lines_changed)}</td></tr><tr><td>Tokens re-detected as real IDs</td><td class="num">–</td><td class="num mono">${a.e9.tokens_redetected_as_real_ids}</td></tr></tbody></table></div>
      <h2 class="h3" style="margin-top:32px">E8: immune layer on six exfiltration scenarios</h2><div class="scroll"><table class="tbl"><thead><tr><th>Method</th><th class="num">Attacks caught</th><th class="num">False alarms</th></tr></thead><tbody>${[['Immune layer (negative selection)', a.e8.ais], ['Static rules', a.e8.static], ['Isolation Forest', a.e8.iforest]].map(([n, v]) => `<tr><td>${n}</td><td class="num mono">${Math.round(v.tpr * 100)}%</td><td class="num mono">${(v.fpr * 100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div></section>
      <section class="card plus" style="margin-top:16px" data-api="GET /api/results → E10-E12 normaliser and registries"><h2 class="h3">E10: hidden identifiers removed, by evasion trick</h2><div class="scroll"><div class="heat" style="grid-template-columns:minmax(180px,1.6fr) repeat(${g.conditions.length},1fr);min-width:560px"><div></div>${g.conditions.map((x) => `<div class="label" style="text-align:center;padding:8px 0">${x}</div>`).join('')}${g.tricks.map((t, i) => `<div class="small" style="padding:8px 0">${t}</div>${g.conditions.map((_, k) => `<div class="cell" style="background:${heat(g.rate[k][i])}">${Math.round(g.rate[k][i] * 100)}%</div>`).join('')}`).join('')}</div></div></section>`;
    },
    mount(root) {
      const timers = [];
      $$('[data-job]', root).forEach((card) => {
        const id = card.dataset.job, run = $('[data-run]', card), st = $('[data-status]', card), out = $('[data-out]', card);
        const show = (j) => {
          out.classList.remove('hidden'); out.textContent = j.output || ''; out.scrollTop = out.scrollHeight;
          if (j.finished == null) { run.disabled = true; run.firstElementChild.textContent = 'Running…'; st.innerHTML = `<span class="spinner" style="display:inline-block;width:14px;height:14px;margin:0 8px -2px 0;border-width:2px"></span>Started ${Math.round(Date.now() / 1000 - j.started)}s ago · output appears when it finishes`; return false; }
          run.disabled = false; run.firstElementChild.textContent = 'Run again'; const secs = Math.round(j.finished - j.started);
          st.innerHTML = j.returncode === 0 ? `<span class="t-ok">✓ Passed in ${secs}s</span>` : `<span class="t-leak">✗ Exit code ${j.returncode} after ${secs}s</span>`; return true;
        };
        const watch = () => { const t = setInterval(async () => { try { const j = await A.job(id); if (show(j)) { clearInterval(t); j.returncode === 0 ? A.sound.chime() : A.sound.error(); if (id === 'e1-e4') { await A.refresh('results'); U.toast('Results updated'); } } } catch (e) { clearInterval(t); } }, 2000); timers.push(t); };
        A.job(id).then((j) => { if (j && !show(j)) watch(); }).catch(() => {});
        run.onclick = async () => { try { show(await A.job(id, true)); watch(); A.sound.click(); } catch (e) { st.innerHTML = U.note('err', U.esc(e.message)); } };
      });
      return () => timers.forEach(clearInterval); } };

  /* ============================================================ 8 How it works */
  P.about = {
    eyebrow: 'HOW IT WORKS', title: 'Five mechanisms, each built on a named theory.', lede: '',
    view() {
      const M = [['M1', 'Checksum-complement tokens', 'Tokens keep the 12 or 16 digit shape but always fail Verhoeff or Luhn, so any scanner can tell a token from a real number.', ['Dihedral group D5', 'FF1 (NIST SP 800-38G)']], ['M2', 'Evidence-fusion detector', 'A calibrated probability per value from the checksum, the context, NER, the own-customer registry and the trace-bound OTP registry.', ['Bayes’ rule', 'Isotonic calibration', 'Cuckoo filter']], ['M3', 'Per-sink tokens', 'Every destination gets different tokens, so a leaked token names the system that leaked it.', ['PRP families', 'Maximum likelihood']], ['M4', 'Leakage ledger', 'Caps how many bits any group of destinations can learn about one customer. Built in research/firewall and measured in E13.', ['Min-entropy']], ['M5', 'Purpose-bound crypto-shredding', 'One key per customer per purpose; destroying it erases every copy everywhere, with a signed Merkle receipt.', ['AES-256-GCM', 'Ed25519 + ML-DSA-65', 'RFC 6962 Merkle log']]];
      const box = (x, y, w, t, s, hl) => `<g class="${hl ? 'hl' : ''}" transform="translate(${x} ${y})"><rect width="${w}" height="54"/><text x="${w / 2}" y="24">${t}</text><text class="s" x="${w / 2}" y="40">${s}</text></g>`;
      return `<div class="mech">${M.map(([c, t, d, ch]) => `<div class="card plus" data-reveal><span class="label">${c}</span><h2 class="h3">${t}</h2><p class="small muted">${d}</p><div class="chips">${ch.map((x) => U.chip(x)).join('')}</div></div>`).join('')}
        <div class="card plus" data-reveal><span class="label">AI layers + post-quantum</span><h2 class="h3">Added on top</h2><p class="small muted">The AI gateway gives chatbots placeholders only, by role, with a hash-chained audit log. Receipts are signed twice (Ed25519 and ML-DSA-65) and vault keys can be sealed with ML-KEM.</p><div class="chips">${['AI gateway', 'ML-DSA-65', 'ML-KEM', 'CBOM scanner'].map((x) => U.chip(x)).join('')}</div></div></div>
      <section class="card plus" style="margin-top:16px" data-reveal><h2 class="h3">Architecture</h2><div class="scroll"><svg class="arch" viewBox="0 0 1000 250" style="min-width:760px" role="img" aria-label="Sources feed the normaliser, detector, registries and token or vault stage, which feeds the sinks. The immune layer watches the flows and the AI gateway is one sink."><defs><marker id="ah" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="var(--text-2-color)" stroke="none"/></marker></defs>${box(10, 98, 110, 'Sources', '7 systems')}${box(160, 98, 130, 'Normaliser', 'undo disguises', 1)}${box(330, 98, 130, 'Detector', 'calibrated p', 1)}${box(500, 98, 130, 'Registries', 'customers · OTP', 1)}${box(670, 98, 130, 'Token / vault', 'FF1 · AES-GCM', 1)}${box(850, 28, 140, 'Sinks', 'logs · CRM · vendor')}${box(850, 170, 140, 'AI gateway', 'roles · audit')}${box(330, 4, 300, 'Immune layer', 'watches every flow window')}<path d="M120,125 H160"/><path d="M290,125 H330"/><path d="M460,125 H500"/><path d="M630,125 H670"/><path d="M800,115 L850,65"/><path d="M800,140 L850,190"/><path class="dash" d="M480,58 V98"/></svg></div></section>
      <section class="card plus" style="margin-top:16px" data-reveal><h2 class="h3">What runs behind this console</h2><ul class="small muted" style="line-height:1.9;padding-left:20px"><li>The detector, NER and context models are trained by <code>app/server/build_models.py</code> on public corpora (CoNLL-2003, HiNER, Hinglish tweets, UCI SMS, Loghub), the same training as experiment E7.</li><li>Every request goes through <code>research/firewall</code>: normaliser, registries, typo repair, then per-sink tokens or purpose-bound vault tokens.</li><li>Keys live in memory only and the server forgets everything on restart, so no state survives a redeploy.</li><li>Customers are generated: their identifiers pass Verhoeff and Luhn but belong to no real person.</li><li>Honest note: treating crypto-shredding as DPDP erasure still needs legal confirmation.</li></ul></section>
      <section class="card plus" style="margin-top:16px" data-reveal><h2 class="h3">Team Iravora Void · Kalasalingam Academy of Research and Education</h2><div class="team">${U.member('IS', 'Inbathamizhan S', 'Team lead · Cybersecurity')}${U.member('AA', 'Aasif Ahmed A', 'Cybersecurity')}${U.member('SA', 'SN Arun Vijay', 'AI/ML')}${U.member('BM', 'Bharadhwaj M', 'AI/ML')}</div></section>`;
    },
    mount: () => () => {},
  };
})(window.ARAN);
